// unsigned 64-bit divide: r2 = r2 / r3, r3 = r2 % r3 (uses r4; r0, r1 kept)
__crt___udivmod:
    test    r3
    jump    n, __crt___udivmod_big
    move    r4, r2
    rshift  r4, 1
    div     r4, r3
    lshift  r4, 1
    push    r4
    mult    r4, r3
    sub     r2, r4
    pop     r4
    test    r2
    jump    n, __crt___udivmod_fix
    cmp     r2, r3
    jump    lt, __crt___udivmod_done
__crt___udivmod_fix:
    add     r4, 1
    sub     r2, r3
__crt___udivmod_done:
    move    r3, r2
    move    r2, r4
    return
__crt___udivmod_big:
    move    r4, 0
    test    r2
    jump    nn, __crt___udivmod_done
    cmp     r2, r3
    jump    lt, __crt___udivmod_done
    move    r4, 1
    sub     r2, r3
    jump    __crt___udivmod_done

